/** Physical private files, actual Spring/JPA completion boundaries and isolated PostgreSQL.
 * No fake owner is attached to unregistered bytes; no real account/provider is used. */
class DriverDocumentsRetentionIT {
    @TempDir Path temporary;private static RealPostgres database;private ServletWebServerApplicationContext app;private JdbcTemplate sql;private Path storage,operations,journalPath;private String[] args;
    private static final byte[] BYTES="%PDF-1.7\nSynthetic orphan evidence\n%%EOF".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
    private static final String PASSWORD="Synthetic orphan recovery test password 2026";
    record Gate(CountDownLatch entered,CountDownLatch release,AtomicReference<UUID> file){}
    static class TestStorage extends PrivateFileStorage {
        final AtomicReference<Gate> gate=new AtomicReference<>();final AtomicBoolean failErase=new AtomicBoolean();TestStorage(StorageSettings settings){super(settings);}
        @Override public void put(String key,byte[] data)throws IOException {super.put(key,data);var current=gate.get();if(current!=null){current.file().set(UUID.fromString(key));current.entered().countDown();try{if(!current.release().await(15,TimeUnit.SECONDS))throw new IOException("Synthetic upload gate timeout.");}catch(InterruptedException stopped){Thread.currentThread().interrupt();throw new IOException("Synthetic upload interrupted.");}}}
        @Override public void eraseVerified(String key)throws IOException {if(failErase.get())throw new IOException("Synthetic physical cleanup failure.");super.eraseVerified(key);}
    }
    @TestConfiguration static class StorageConfig {@Bean @Primary TestStorage testPrivateStorage(StorageSettings settings){return new TestStorage(settings);}}
    @BeforeAll static void database(){database=new RealPostgres();}
    @AfterAll static void databaseClose(){if(database!=null)database.close();}
    @AfterEach void close(){if(app!=null){app.close();app=null;}}
    @BeforeEach void setup()throws Exception {
        database.resetSchema();storage=temporary.resolve("files");operations=temporary.resolve("ops");journalPath=temporary.resolve("journal");var values=new ArrayList<>(List.of(AuthTestSettings.arguments(database.apiConnectionUrl())));values.addAll(List.of("--STORAGE_PATH="+storage,"--FRONTEND_PATH="+temporary.resolve("public"),"--PRIVACY_OPERATIONS_ROOT="+operations,"--PRIVACY_ERASURE_JOURNAL_PATH="+journalPath,"--DEV_MAIL_PATH="+temporary.resolve("mail")));args=values.toArray(String[]::new);
        var env=new MockEnvironment();for(String arg:args){int at=arg.indexOf('=');env.withProperty(arg.substring(2,at),arg.substring(at+1));}var json=new ObjectMapper();var crypto=new CryptoService();var auth=new AuthSettings(env);var files=new StorageSettings(env);new PrivacyBackupCatalog(new PrivacyOperationsSettings(env,files),new PrivacySettings(env),new PrivacySigningKeys(env,auth,crypto,json),json,Clock.systemUTC()).initialize();start();
    }
    private void start(){app=(ServletWebServerApplicationContext)new SpringApplicationBuilder(UniCaronaApplication.class,StorageConfig.class).run(args);sql=app.getBean(JdbcTemplate.class);}
    private static String sha(byte[] bytes)throws Exception {return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}
    private UUID orphan()throws Exception {UUID file=UUID.randomUUID();app.getBean(PrivateFileStorage.class).put(file.toString(),BYTES);return file;}
    private PrivacyOrphanFileTransactions tx(){return app.getBean(PrivacyOrphanFileTransactions.class);}
    private void age(UUID file){sql.update("UPDATE privacy_orphan_file_observations SET first_seen_at=now()-interval '2 days',last_seen_at=now()-interval '2 days' WHERE file_id=?",file);}
    private PrivacyErasureJournal journal(){return app.getBean(PrivacyErasureJournal.class);}
    private void guard()throws Exception {app.getBean(PrivacyRestoreGuard.class).run(new DefaultApplicationArguments());}
    private Actor owner(){String hash=app.getBean(CryptoService.class).hashPassword(PASSWORD);UUID id=sql.queryForObject("INSERT INTO users(email,password_hash,name,birth_date,email_verified_at) VALUES(?,?,'Synthetic orphan test owner','2000-01-01',now()) RETURNING id",UUID.class,UUID.randomUUID()+"@example.test",hash);return new Actor(id,"user","active",null,null,null,true,Set.of());}
    private void metadata(UUID file,Actor owner)throws Exception {sql.update("INSERT INTO stored_files(id,owner_id,purpose,storage_key,content_type,byte_size,sha256) VALUES(?,?,'identity',?,'application/pdf',?,?)",file,owner.id(),file.toString(),BYTES.length,sha(BYTES));}
    private UUID document(Actor owner,String purpose,boolean old)throws Exception {UUID file=app.getBean(FileService.class).upload(owner,purpose,BYTES).id();if(old)sql.update("UPDATE stored_files SET created_at=now()-interval '2 days',last_uploaded_at=now()-interval '2 days' WHERE id=?",file);return file;}
    private UUID application(Actor owner,String status,UUID identity,UUID license,boolean due){UUID vehicle=sql.queryForObject("INSERT INTO vehicles(owner_id,model,color,plate,capacity,status) VALUES(?,'Synthetic document car','Black','ABC1D23',4,?) RETURNING id",UUID.class,owner.id(),"approved".equals(status)?"approved":"pending");sql.update("INSERT INTO driver_profiles(user_id,status,approved_at) VALUES(?,?,CASE WHEN ? THEN now() ELSE NULL END) ON CONFLICT(user_id) DO UPDATE SET status=excluded.status,approved_at=excluded.approved_at",owner.id(),"approved".equals(status)?"approved":"pending","approved".equals(status));return sql.queryForObject("INSERT INTO driver_applications(user_id,vehicle_id,identity_file_id,license_file_id,status,created_at,reviewed_at,documents_expires_at) VALUES(?,?,?,?,?,now()-interval '60 days',CASE WHEN ? THEN now()-interval '40 days' ELSE NULL END,CASE WHEN ? THEN now()-interval '1 day' ELSE now()+interval '20 days' END) RETURNING id",UUID.class,owner.id(),vehicle,identity,license,status,"approved".equals(status)||"rejected".equals(status),due);}
    private boolean retire(Actor owner,UUID application)throws Exception {return app.getBean(PrivacyDriverDocuments.class).retire(new PrivacyDriverDocuments.Candidate(application,owner.id()),true);}
    private Actor admin(){var owner=owner();sql.update("UPDATE users SET role='admin' WHERE id=?",owner.id());var tokens=app.getBean(com.unicarona.auth.service.AuthService.class).login(sql.queryForObject("SELECT email FROM users WHERE id=?",String.class,owner.id()),PASSWORD).tokens();return new Actor(owner.id(),"admin","active",tokens.sessionId(),null,null,true,Set.of("ROLE_ADMIN"));}
    private com.unicarona.privacy.dto.PrivacyHoldDto.Item hold(Actor admin,Actor owner,UUID file){return app.getBean(AdminPrivacyHoldService.class).create(admin,new com.unicarona.privacy.dto.PrivacyHoldDto.Create(PASSWORD,owner.id(),"files",file,"regular_exercise_of_rights","Synthetic scoped document evidence for this dispute","Synthetic document case",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(86400)),UUID.randomUUID().toString());}
    private String downloadFailure(Actor actor,UUID file){return assertThrows(com.unicarona.shared.ApiException.class,()->app.getBean(FileService.class).download(actor,file)).code();}
    @Test void expirationHidesOrdinaryDocumentsAndReviewActionsBeforeAnyWorkerHasRun()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",true),license=document(owner,"license",true),id=application(owner,"pending",identity,license,true);var admin=admin();var a=app.getBean(com.unicarona.driver.repository.DriverRepository.class).applications(owner.id(),false,10,0,null).getFirst();assertEquals("expired",a.status());assertEquals("expired",a.documentsStatus());assertNull(a.identityFileId());assertNull(a.licenseFileId());assertEquals("FILE_NOT_FOUND",downloadFailure(owner,identity));assertEquals("FILE_NOT_FOUND",downloadFailure(admin,license));assertTrue(Files.exists(storage.resolve(identity.toString())));assertEquals("APPLICATION_DOCUMENTS_EXPIRED",assertThrows(com.unicarona.shared.ApiException.class,()->app.getBean(com.unicarona.driver.service.DriverTransactions.class).review(admin,id.toString(),new com.unicarona.driver.dto.DriverDto.Review(true,"Synthetic review"),UUID.randomUUID().toString())).code());assertEquals("pending",sql.queryForObject("SELECT status FROM driver_profiles WHERE user_id=?",String.class,owner.id()));
    }
    @Test void pendingExpiryIsIdempotentNotifiesOnceAndPhysicalSuppressionIsConfirmedBeforeReadiness()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",true),license=document(owner,"license",true),id=application(owner,"pending",identity,license,true);Timestamp deadline=sql.queryForObject("SELECT documents_expires_at FROM driver_applications WHERE id=?",Timestamp.class,id);assertTrue(retire(owner,id));assertFalse(retire(owner,id));assertEquals("expired",sql.queryForObject("SELECT status FROM driver_applications WHERE id=?",String.class,id));assertEquals("rejected",sql.queryForObject("SELECT status FROM driver_profiles WHERE user_id=?",String.class,owner.id()));assertEquals(1,sql.queryForObject("SELECT count(*) FROM notifications WHERE user_id=? AND title='Solicitação de motorista vencida'",Integer.class,owner.id()));assertEquals(deadline,sql.queryForObject("SELECT documents_expires_at FROM driver_applications WHERE id=?",Timestamp.class,id));guard();for(UUID file:List.of(identity,license)){assertFalse(Files.exists(storage.resolve(file.toString())));assertNotNull(journal().fileEntries().stream().filter(e->e.file().equals(file)).findFirst().orElseThrow().confirmedAt());}assertTrue(app.getBean(PrivacyReadiness.class).ready());
    }
    @Test void retiringApprovedCopiesPreservesTheApprovalVehicleAndFinancialLedger()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",true),license=document(owner,"license",true),id=application(owner,"approved",identity,license,true);String vehicle=sql.queryForObject("SELECT to_jsonb(v)::text FROM vehicles v JOIN driver_applications a ON a.vehicle_id=v.id WHERE a.id=?",String.class,id);app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{UUID clearing=sql.queryForObject("INSERT INTO ledger_accounts(kind) VALUES('provider_clearing') RETURNING id",UUID.class),credit=sql.queryForObject("INSERT INTO ledger_accounts(owner_id,kind) VALUES(?,'passenger_credit') RETURNING id",UUID.class,owner.id()),transaction=sql.queryForObject("INSERT INTO ledger_transactions(event_key,kind,reason,body_hash) VALUES(?,'synthetic_document_retention','Synthetic credit preservation',?) RETURNING id",UUID.class,"document-retention:"+UUID.randomUUID(),"b".repeat(64));sql.update("INSERT INTO ledger_entries(transaction_id,account_id,cents) VALUES(?,?,-700),(?,?,700)",transaction,clearing,transaction,credit);});assertTrue(retire(owner,id));guard();assertEquals("approved",sql.queryForObject("SELECT status FROM driver_profiles WHERE user_id=?",String.class,owner.id()));assertEquals("approved",sql.queryForObject("SELECT status FROM driver_applications WHERE id=?",String.class,id));assertEquals(vehicle,sql.queryForObject("SELECT to_jsonb(v)::text FROM vehicles v JOIN driver_applications a ON a.vehicle_id=v.id WHERE a.id=?",String.class,id));assertEquals(700L,sql.queryForObject("SELECT sum(e.cents) FROM ledger_entries e JOIN ledger_accounts a ON a.id=e.account_id WHERE a.owner_id=?",Long.class,owner.id()));assertEquals("active",sql.queryForObject("SELECT account_status FROM users WHERE id=?",String.class,owner.id()));
    }
    @Test void aSharedDocumentIsNotDeletedWhileAnotherApplicationStillHasALivePurpose()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",true),license=document(owner,"license",true),old=application(owner,"replaced",identity,license,true),current=application(owner,"pending",identity,license,false);assertTrue(retire(owner,old));guard();assertArrayEquals(BYTES,app.getBean(FileService.class).download(owner,identity).data());assertNull(sql.queryForObject("SELECT erasure_requested_at FROM stored_files WHERE id=?",Timestamp.class,identity));sql.update("UPDATE driver_applications SET documents_expires_at=now()-interval '1 second' WHERE id=?",current);guard();assertFalse(Files.exists(storage.resolve(identity.toString())));assertFalse(Files.exists(storage.resolve(license.toString())));
    }
    @Test void anExplicitRecentReuploadRetainsOnlyTheNewUnlinkedFormAllowance()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",true),license=document(owner,"license",true),id=application(owner,"rejected",identity,license,true);assertEquals(identity,app.getBean(FileService.class).upload(owner,"identity",BYTES).id());assertTrue(retire(owner,id));guard();assertArrayEquals(BYTES,app.getBean(FileService.class).download(owner,identity).data());assertNull(sql.queryForObject("SELECT erasure_requested_at FROM stored_files WHERE id=?",Timestamp.class,identity));assertFalse(Files.exists(storage.resolve(license.toString())));assertEquals("retired",app.getBean(com.unicarona.driver.repository.DriverRepository.class).applications(owner.id(),false,1,0,null).getFirst().documentsStatus());
    }
    @Test void reviewVerifiesPhysicalBytesAndIdempotentRetryDoesNotRenewTheRetentionDeadline()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",false),license=document(owner,"license",false),id=application(owner,"pending",identity,license,false);var admin=admin();var reviews=app.getBean(com.unicarona.driver.service.DriverTransactions.class);Files.write(storage.resolve(identity.toString()),new byte[]{9,8,7});assertEquals("APPLICATION_DOCUMENTS_UNAVAILABLE",assertThrows(com.unicarona.shared.ApiException.class,()->reviews.review(admin,id.toString(),new com.unicarona.driver.dto.DriverDto.Review(true,"Synthetic review"),UUID.randomUUID().toString())).code());assertEquals("pending",sql.queryForObject("SELECT status FROM driver_profiles WHERE user_id=?",String.class,owner.id()));Files.write(storage.resolve(identity.toString()),BYTES);String key=UUID.randomUUID().toString();var body=new com.unicarona.driver.dto.DriverDto.Review(true,"Synthetic physical document review");assertEquals("approved",reviews.review(admin,id.toString(),body,key).status());Timestamp deadline=sql.queryForObject("SELECT documents_expires_at FROM driver_applications WHERE id=?",Timestamp.class,id);assertTrue(sql.queryForObject("SELECT documents_expires_at=reviewed_at+interval '30 days' FROM driver_applications WHERE id=?",Boolean.class,id));assertEquals("approved",reviews.review(admin,id.toString(),body,key).status());assertEquals(deadline,sql.queryForObject("SELECT documents_expires_at FROM driver_applications WHERE id=?",Timestamp.class,id));
    }
    @Test void aRestrictedAccountCannotBeApprovedByAStaleAdministratorScreen()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",false),license=document(owner,"license",false),id=application(owner,"pending",identity,license,false);var admin=admin();sql.update("UPDATE users SET account_status='closing' WHERE id=?",owner.id());assertThrows(com.unicarona.shared.ApiException.class,()->app.getBean(com.unicarona.driver.service.DriverTransactions.class).review(admin,id.toString(),new com.unicarona.driver.dto.DriverDto.Review(true,"Synthetic stale review"),UUID.randomUUID().toString()));assertEquals("pending",sql.queryForObject("SELECT status FROM driver_profiles WHERE user_id=?",String.class,owner.id()));
    }
    @Test void aSpecificPreservationSurvivesExpiryPrivatelyAndARealOldArchiveCannotRelinkIt()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",true),license=document(owner,"license",true),id=application(owner,"approved",identity,license,false);sql.update("UPDATE driver_applications SET documents_expires_at=clock_timestamp()+interval '2 seconds' WHERE id=?",id);Instant deadline=sql.queryForObject("SELECT documents_expires_at FROM driver_applications WHERE id=?",Timestamp.class,id).toInstant();Path archive=temporary.resolve("before-document-expiry.dump");var admin=admin();database.dumpDatabaseArchive(archive);var hold=hold(admin,owner,identity);long wait=Duration.between(Instant.now(),deadline.plusMillis(100)).toMillis();assertTrue(wait<8000);if(wait>0)Thread.sleep(wait);assertTrue(retire(owner,id));guard();assertEquals("FILE_NOT_FOUND",downloadFailure(owner,identity));assertEquals("FILE_NOT_FOUND",downloadFailure(admin,identity));assertArrayEquals(BYTES,app.getBean(AdminPrivacyHoldService.class).heldData(admin,hold.id(),new com.unicarona.privacy.dto.PrivacyDto.Reauthenticate(PASSWORD)).data());assertFalse(Files.exists(storage.resolve(license.toString())));app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(archive);start();assertTrue(app.getBean(PrivacyReadiness.class).ready());assertNull(sql.queryForObject("SELECT identity_file_id FROM driver_applications WHERE id=?",UUID.class,id));assertEquals("approved",sql.queryForObject("SELECT status FROM driver_profiles WHERE user_id=?",String.class,owner.id()));assertArrayEquals(BYTES,Files.readAllBytes(storage.resolve(identity.toString())));assertFalse(Files.exists(storage.resolve(license.toString())));assertEquals("FILE_NOT_FOUND",downloadFailure(owner,identity));
    }
    @Test void failedPhysicalCleanupBlocksReadinessAndRetainsTheOriginalInstructionForRetry()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",true),license=document(owner,"license",true);application(owner,"pending",identity,license,true);app.getBean(TestStorage.class).failErase.set(true);assertThrows(Exception.class,this::guard);assertFalse(app.getBean(PrivacyReadiness.class).ready());var pending=journal().fileEntries().getFirst();assertNull(pending.confirmedAt());assertTrue(Files.exists(storage.resolve(identity.toString())));app.getBean(TestStorage.class).failErase.set(false);guard();assertTrue(app.getBean(PrivacyReadiness.class).ready());var confirmed=journal().fileEntries().stream().filter(e->e.file().equals(pending.file())).findFirst().orElseThrow();assertEquals(pending.preparedAt(),confirmed.preparedAt());assertNotNull(confirmed.confirmedAt());
    }
    @Test void metadataExpiresOnlyAfterPhysicalAbsenceAndReplayStillProtectsAMissingRow()throws Exception {
        var owner=owner();UUID file=document(owner,"identity",true);sql.update("UPDATE stored_files SET deleted_at=now(),erasure_requested_at=now() WHERE id=?",file);assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));var proof=journal().fileEntries().getFirst();sql.update("UPDATE stored_files SET deleted_at=now()-interval '93 days',erasure_requested_at=now()-interval '92 days',erased_at=now()-interval '91 days' WHERE id=?",file);assertTrue(app.getBean(PrivacyFileMetadataRetention.class).retire(new PrivacyFileMetadataRetention.Candidate(file,owner.id())));assertFalse(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM stored_files WHERE id=?)",Boolean.class,file));assertEquals(proof,journal().fileEntries().getFirst());Files.write(storage.resolve(file.toString()),BYTES);guard();assertFalse(Files.exists(storage.resolve(file.toString())));assertEquals("active",sql.queryForObject("SELECT account_status FROM users WHERE id=?",String.class,owner.id()));
    }
    @Test void metadataWithReintroducedBytesIsPreservedUntilTheErasurePathRechecksIt()throws Exception {
        var owner=owner();UUID file=document(owner,"identity",true);sql.update("UPDATE stored_files SET deleted_at=now(),erasure_requested_at=now() WHERE id=?",file);assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));sql.update("UPDATE stored_files SET deleted_at=now()-interval '93 days',erasure_requested_at=now()-interval '92 days',erased_at=now()-interval '91 days' WHERE id=?",file);Files.write(storage.resolve(file.toString()),BYTES);assertFalse(app.getBean(PrivacyFileMetadataRetention.class).retire(new PrivacyFileMetadataRetention.Candidate(file,owner.id())));assertArrayEquals(BYTES,Files.readAllBytes(storage.resolve(file.toString())));assertTrue(app.getBean(PrivacyFileErasure.class).suppressRecorded(file));assertFalse(Files.exists(storage.resolve(file.toString())));assertFalse(app.getBean(PrivacyFileMetadataRetention.class).retire(new PrivacyFileMetadataRetention.Candidate(file,owner.id())),"A new physical removal has its own recent metadata allowance");
    }
    @Test void ownerContentionDoesNotDeleteSharedBytesOrStarveAnotherExpiredMetadataRecord()throws Exception {
        var owners=List.of(owner(),owner());for(var owner:owners){UUID file=document(owner,"identity",true);sql.update("UPDATE stored_files SET deleted_at=now(),erasure_requested_at=now() WHERE id=?",file);assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));sql.update("UPDATE stored_files SET deleted_at=now()-interval '93 days',erasure_requested_at=now()-interval '92 days',erased_at=now()-interval '91 days' WHERE id=?",file);}var first=app.getBean(PrivacyFileMetadataRetention.class).candidates(null,1).getFirst();var locked=new CountDownLatch(1);var release=new CountDownLatch(1);try(var executor=Executors.newVirtualThreadPerTaskExecutor()){var writer=executor.submit(()->app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{sql.queryForList("SELECT id FROM users WHERE id=? FOR UPDATE",first.owner());locked.countDown();try{assertTrue(release.await(15,TimeUnit.SECONDS));}catch(InterruptedException stop){Thread.currentThread().interrupt();throw new IllegalStateException(stop);}}));try{assertTrue(locked.await(8,TimeUnit.SECONDS));assertEquals(0,app.getBean(PrivacyFileMetadataMaintenance.class).runOnce(1,()->false));assertEquals(1,app.getBean(PrivacyFileMetadataMaintenance.class).runOnce(1,()->false));assertTrue(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM stored_files WHERE id=?)",Boolean.class,first.id()));}finally{release.countDown();}writer.get(8,TimeUnit.SECONDS);}finally{release.countDown();}
    }
    @Test void ownerExportIncludesLifecycleInformationButDoesNotBundleExpiredRawCopies()throws Exception {
        var owner=owner();UUID identity=document(owner,"identity",true),license=document(owner,"license",true);application(owner,"pending",identity,license,true);var result=new java.io.ByteArrayOutputStream();app.getBean(PrivacyExportService.class).write(owner.id(),result);boolean data=false;try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(result.toByteArray()))){for(var entry=zip.getNextEntry();entry!=null;entry=zip.getNextEntry()){assertFalse(entry.getName().startsWith("documentos/"));if(entry.getName().equals("dados.json")){var tree=app.getBean(ObjectMapper.class).readTree(zip.readAllBytes());assertEquals("driver-documents-v1",tree.path("driverApplications").get(0).path("documents_policy_version").asText());assertNotNull(tree.path("driverApplications").get(0).get("documents_expires_at"));data=true;}}}assertTrue(data);assertTrue(Files.exists(storage.resolve(identity.toString())));
    }
    @Test void legacyHeldFileRecoveryUsesCreationRatherThanInventingARecentUpload()throws Exception {
        var owner=owner();var admin=admin();Path archive=temporary.resolve("before-legacy-held-document.dump");database.dumpDatabaseArchive(archive);UUID file=document(owner,"identity",true);Timestamp created=sql.queryForObject("SELECT created_at FROM stored_files WHERE id=?",Timestamp.class,file);var hold=hold(admin,owner,file);var legacy=app.getBean(PrivacyHoldControlJournal.class).current().orElseThrow().state().deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)legacy).put("format",1);for(var row:legacy.path("files"))((com.fasterxml.jackson.databind.node.ObjectNode)row).remove("lastUploadedAt");app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->app.getBean(PrivacyHoldControlTransactions.class).stage(()->legacy));app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(archive);start();assertTrue(app.getBean(PrivacyReadiness.class).ready());assertEquals(created,sql.queryForObject("SELECT last_uploaded_at FROM stored_files WHERE id=?",Timestamp.class,file));assertTrue(sql.queryForObject("SELECT last_uploaded_at=created_at AND last_uploaded_at<now()-interval '1 day' AND deleted_at IS NOT NULL AND erasure_requested_at IS NOT NULL FROM stored_files WHERE id=?",Boolean.class,file));assertEquals("FILE_NOT_FOUND",downloadFailure(owner,file));assertArrayEquals(BYTES,app.getBean(AdminPrivacyHoldService.class).heldData(admin,hold.id(),new com.unicarona.privacy.dto.PrivacyDto.Reauthenticate(PASSWORD)).data());assertEquals(3,app.getBean(PrivacyHoldControlJournal.class).current().orElseThrow().state().path("format").asInt());
    }
    @Test void oneConflictingMetadataRecordDoesNotStarveTheOtherExpiredRecords()throws Exception {
        for(var owner:List.of(owner(),owner())){UUID file=document(owner,"identity",true);sql.update("UPDATE stored_files SET deleted_at=now(),erasure_requested_at=now() WHERE id=?",file);assertTrue(app.getBean(PrivacyFileErasure.class).erase(file));sql.update("UPDATE stored_files SET deleted_at=now()-interval '93 days',erasure_requested_at=now()-interval '92 days',erased_at=now()-interval '91 days' WHERE id=?",file);}var conflict=app.getBean(PrivacyFileMetadataRetention.class).candidates(null,1).getFirst();sql.update("UPDATE stored_files SET storage_key=? WHERE id=?",UUID.randomUUID().toString(),conflict.id());var task=app.getBean(PrivacyFileMetadataMaintenance.class);assertThrows(IOException.class,()->task.runOnce(1,()->false));assertEquals(1,task.runOnce(1,()->false));assertTrue(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM stored_files WHERE id=?)",Boolean.class,conflict.id()));
    }
}
